    "sql": "DO $$\nDECLARE\nr RECORD;\nv_save_data JSONB;\nv_eggs JSONB;\nv_new_eggs JSONB;\nv_egg JSONB;\nv_egg_nature TEXT;\nv_nature_map JSONB;\nv_key TEXT;\nv_new_nature TEXT;\nBEGIN\nv_nature_map := '{\n\"serio\": \"serious\",\n\"seria\": \"serious\",\n\"serious\": \"serious\",\n\"firme\": \"adamant\",\n\"adamant\": \"adamant\",\n\"timido\": \"bashful\",\n\"timida\": \"bashful\",\n\"tímido\": \"bashful\",\n\"tímida\": \"bashful\",\n\"bashful\": \"bashful\",\n\"osado\": \"bold\",\n\"osada\": \"bold\",\n\"bold\": \"bold\",\n\"audaz\": \"brave\",\n\"brave\": \"brave\",\n\"sereno\": \"calm\",\n\"serena\": \"calm\",\n\"calm\": \"calm\",\n\"cauto\": \"careful\",\n\"cauta\": \"careful\",\n\"careful\": \"careful\",\n\"docil\": \"docile\",\n\"dócil\": \"docile\",\n\"docile\": \"docile\",\n\"amable\": \"gentle\",\n\"gentle\": \"gentle\",\n\"fuerte\": \"hardy\",\n\"hardy\": \"hardy\",\n\"activa\": \"hasty\",\n\"activo\": \"hasty\",\n\"active\": \"hasty\",\n\"hasty\": \"hasty\",\n\"agitada\": \"impish\",\n\"agitado\": \"impish\",\n\"impish\": \"impish\",\n\"alegre\": \"jolly\",\n\"jovial\": \"jolly\",\n\"jolly\": \"jolly\",\n\"floja\": \"lax\",\n\"flojo\": \"lax\",\n\"lax\": \"lax\",\n\"hurana\": \"lonely\",\n\"hurano\": \"lonely\",\n\"huraña\": \"lonely\",\n\"huraño\": \"lonely\",\n\"lonely\": \"lonely\",\n\"afable\": \"mild\",\n\"moderada\": \"mild\",\n\"moderado\": \"mild\",\n\"mild\": \"mild\",\n\"modesta\": \"modest\",\n\"modesto\": \"modest\",\n\"modest\": \"modest\",\n\"ingenua\": \"naive\",\n\"ingenuo\": \"naive\",\n\"naive\": \"naive\",\n\"picara\": \"naughty\",\n\"picaro\": \"naughty\",\n\"pícara\": \"naughty\",\n\"pícaro\": \"naughty\",\n\"naughty\": \"naughty\",\n\"mansa\": \"quiet\",\n\"manso\": \"quiet\",\n\"tranquila\": \"quiet\",\n\"tranquilo\": \"quiet\",\n\"tasa\": \"quiet\",\n\"quiet\": \"quiet\",\n\"rara\": \"quirky\",\n\"raro\": \"quirky\",\n\"quirky\": \"quirky\",\n\"alocada\": \"rash\",\n\"alocado\": \"rash\",\n\"rash\": \"rash\",\n\"placida\": \"relaxed\",\n\"placido\": \"relaxed\",\n\"plácida\": \"relaxed\",\n\"plácido\": \"relaxed\",\n\"relaxed\": \"relaxed\",\n\"grosera\": \"sassy\",\n\"grosero\": \"sassy\",\n\"sassy\": \"sassy\",\n\"miedosa\": \"timid\",\n\"miedoso\": \"timid\",\n\"timid\": \"timid\"\n}'::jsonb;\nFOR r IN SELECT user_id, save_data FROM public.game_saves LOOP\nv_save_data := r.save_data;\nv_eggs := v_save_data -> 'eggs';\nIF v_eggs IS NOT NULL AND jsonb_typeof(v_eggs) = 'array' THEN\nv_new_eggs := '[]'::jsonb;\nFOR v_egg IN SELECT * FROM jsonb_array_elements(v_eggs) LOOP\nv_egg_nature := v_egg ->> 'nature';\nIF v_egg_nature IS NOT NULL THEN\nv_key := lower(v_egg_nature);\nIF v_nature_map ->> v_key IS NOT NULL THEN\nv_new_nature := v_nature_map ->> v_key;\nv_egg := jsonb_set(v_egg, '{nature}', to_jsonb(v_new_nature));\nEND IF;\nEND IF;\nv_new_eggs := v_new_eggs || v_egg;\nEND LOOP;\nv_save_data := jsonb_set(v_save_data, '{eggs}', v_new_eggs);\nEND IF;\nUPDATE public.game_saves\nSET save_data = v_save_data\nWHERE user_id = r.user_id;\nEND LOOP;\nINSERT INTO public.system_config (key, value)\nVALUES ('db_version', '20260701100000'::jsonb)\nON CONFLICT (key)\nDO UPDATE SET value = EXCLUDED.value, updated_at = NOW();\nEND $$;",
    "sqlite_sql": "UPDATE game_saves\nSET save_data = json_set(\nsave_data,\n'$.eggs',\n(\nSELECT json_group_array(\nCASE\nWHEN json_extract(egg_item.value, '$.nature') IS NULL OR json_extract(egg_item.value, '$.nature') = '' THEN\njson_set(egg_item.value, '$.nature', 'serious')\nELSE\njson_set(\negg_item.value,\n'$.nature',\ncoalesce(\njson_extract(\n'{\"serio\":\"serious\",\"seria\":\"serious\",\"serious\":\"serious\",\"firme\":\"adamant\",\"adamant\":\"adamant\",\"timido\":\"bashful\",\"timida\":\"bashful\",\"tímido\":\"bashful\",\"tímida\":\"bashful\",\"bashful\":\"bashful\",\"osado\":\"bold\",\"osada\":\"bold\",\"bold\":\"bold\",\"audaz\":\"brave\",\"brave\":\"brave\",\"sereno\":\"calm\",\"serena\":\"calm\",\"calm\":\"calm\",\"cauto\":\"careful\",\"cauta\":\"careful\",\"careful\":\"careful\",\"docil\":\"docile\",\"dócil\":\"docile\",\"docile\":\"docile\",\"amable\":\"gentle\",\"gentle\":\"gentle\",\"fuerte\":\"hardy\",\"hardy\":\"hardy\",\"activa\":\"hasty\",\"activo\":\"hasty\",\"active\":\"hasty\",\"hasty\":\"hasty\",\"agitada\":\"impish\",\"agitado\":\"impish\",\"impish\":\"impish\",\"alegre\":\"jolly\",\"jovial\":\"jolly\",\"jolly\":\"jolly\",\"floja\":\"lax\",\"flojo\":\"lax\",\"lax\":\"lax\",\"hurana\":\"lonely\",\"hurano\":\"lonely\",\"huraña\":\"lonely\",\"huraño\":\"lonely\",\"lonely\":\"lonely\",\"afable\":\"mild\",\"moderada\":\"mild\",\"moderado\":\"mild\",\"mild\":\"mild\",\"modesta\":\"modest\",\"modesto\":\"modest\",\"modest\":\"modest\",\"ingenua\":\"naive\",\"ingenuo\":\"naive\",\"naive\":\"naive\",\"picara\":\"naughty\",\"picaro\":\"naughty\",\"pícara\":\"naughty\",\"pícaro\":\"naughty\",\"naughty\":\"naughty\",\"mansa\":\"quiet\",\"manso\":\"quiet\",\"tranquila\":\"quiet\",\"tranquilo\":\"quiet\",\"tasa\":\"quiet\",\"quiet\":\"quiet\",\"rara\":\"quirky\",\"raro\":\"quirky\",\"quirky\":\"quirky\",\"alocada\":\"rash\",\"alocado\":\"rash\",\"rash\":\"rash\",\"placida\":\"relaxed\",\"placido\":\"relaxed\",\"plácida\":\"relaxed\",\"plácido\":\"relaxed\",\"relaxed\":\"relaxed\",\"grosera\":\"sassy\",\"grosero\":\"sassy\",\"sassy\":\"sassy\",\"miedosa\":\"timid\",\"miedoso\":\"timid\",\"timid\":\"timid\"}',\n'$.' || lower(json_extract(egg_item.value, '$.nature'))\n),\nlower(json_extract(egg_item.value, '$.nature'))\n)\n)\nEND\n)\nFROM json_each(json_extract(game_saves.save_data, '$.eggs')) egg_item\n)\n)\nWHERE save_data IS NOT NULL AND json_extract(save_data, '$.eggs') IS NOT NULL;\nINSERT INTO system_config (key, value, updated_at)\nVALUES ('db_version', '20260701100000', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))\nON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at;",
    "check": null
